{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.PLAETO_PANDL_INTERMEDIATE AS SELECT FINAL_MARKETPLACE, MARKETPLACE, CHANNEL, ORDER_ID, REFERENCE_CODE, CAST(SHIPPING_LAST_UPDATE_DATE AS TIMESTAMP) AS SHIPPING_LAST_UPDATE_DATE, SKU, PRODUCT_NAME, CAST(ORDER_DATE AS DATE) AS ORDER_DATE, CAST(NULL AS DATE) AS RETURN_DATE, CAST(QUANTITY AS INT64) AS SALES_QUANTITY, CAST(NULL AS INT64) AS RETURN_QUANTITY, CAST(MRP AS FLOAT64) AS MRP, CAST(DISCOUNT AS FLOAT64) AS DISCOUNT, CAST(SHIPPING_PRICE AS FLOAT64) AS SHIPPING_PRICE, CAST(SELLING_PRICE AS FLOAT64) AS SELLING_PRICE, CAST(GROSS_SALES_BEFORE_TAX AS FLOAT64) AS GROSS_SALES_BEFORE_TAX, CAST(GROSS_SALES_AFTER_TAX AS FLOAT64) AS GROSS_SALES_AFTER_TAX, CAST(TAX AS FLOAT64) AS TAX, CAST(NULL AS FLOAT64) AS RETURN_TAX, CAST(NULL AS FLOAT64) AS RETURN_AMOUNT, PRODUCT_CATEGORY FROM `plaeup-wh.maplemonk.plaeup_wh_sales_consolidated` UNION ALL SELECT FINAL_MARKETPLACE, MARKETPLACE, MARKETING_CHANNEL AS CHANNEL, CAST(NULL AS STRING) AS ORDER_ID, REFERENCE_CODE, CAST(NULL AS TIMESTAMP) AS SHIPPING_LAST_UPDATE_DATE, CAST(SKU AS STRING) AS SKU, CAST(NULL AS STRING) AS PRODUCT_NAME, CAST(Order_Date AS DATE) AS ORDER_DATE, CAST(RETURN_DATE AS DATE) AS RETURN_DATE, CAST(NULL AS INT64) AS SALES_QUANTITY, CAST(TOTAL_RETURNED_QUANTITY AS INT64) AS RETURN_QUANTITY, CAST(NULL AS FLOAT64) AS MRP, CAST(NULL AS FLOAT64) AS DISCOUNT, CAST(NULL AS FLOAT64) AS SHIPPING_PRICE, CAST(NULL AS FLOAT64) AS SELLING_PRICE, CAST(NULL AS FLOAT64) AS GROSS_SALES_BEFORE_TAX, CAST(NULL AS FLOAT64) AS GROSS_SALES_AFTER_TAX, CAST(NULL AS FLOAT64) AS TAX, CAST(TOTAL_RETURN_TAX AS FLOAT64) AS RETURN_TAX, CAST(TOTAL_RETURN_AMOUNT AS FLOAT64) AS RETURN_AMOUNT, CAST(NULL AS STRING) AS PRODUCT_CATEGORY FROM `plaeup-wh.maplemonk.plaeup_wh_returns_consolidated`; CREATE OR REPLACE TABLE MAPLEMONK.PLAETO_PANDL AS SELECT COALESCE(UPPER(A.FINAL_MARKETPLACE),UPPER(D.FINAL_MARKETPLACE)) FINAL_MARKETPLACE ,CASE WHEN LOWER(a.marketplace) LIKE ANY (\'%shopify%\',\'%website%\') THEN \'WEBSITE\' WHEN LOWER(a.marketplace) LIKE \'%myntra%\' THEN \'MYNTRA\' WHEN LOWER(a.marketplace) LIKE \'%amazon%\' THEN \'AMAZON\' WHEN REPLACE(LOWER(TRIM(a.marketplace)), \' \', \'\') LIKE \'%plaeup%\' THEN \'PLAEUP_B2B\' WHEN REPLACE(LOWER(TRIM(a.marketplace)), \' \', \'\') LIKE \'%plaeto%\' THEN \'PLAEUP_CS\' WHEN LOWER(a.marketplace) LIKE \'%ajio%\' THEN \'AJIO\' WHEN LOWER(a.marketplace) LIKE \'%cred%\' THEN \'CRED\' WHEN LOWER(a.marketplace) LIKE \'%cocoblu_blr%\' THEN \'COCOBLU_BLR\' WHEN LOWER(a.marketplace) LIKE \'%flipkart%\' THEN \'FLIPKART\' END AS MARKETPLACE ,ORDER_ID ,REFERENCE_CODE ,SHIPPING_LAST_UPDATE_DATE ,SKU ,COALESCE(A.PRODUCT_NAME, B.PRODUCT_NAME) AS PRODUCT_NAME ,ORDER_DATE ,RETURN_DATE ,SALES_QUANTITY ,RETURN_QUANTITY ,COALESCE(A.MRP,B.MRP) MRP ,DISCOUNT ,SHIPPING_PRICE ,SELLING_PRICE ,GROSS_SALES_BEFORE_TAX ,GROSS_SALES_AFTER_TAX ,TAX ,RETURN_TAX ,RETURN_AMOUNT ,PRODUCT_CATEGORY ,B.COGS AS COGS ,B.PACKAGING_COST AS PACKAGING_COST ,C.SPEND ,C.IMPRESSIONS ,C.CLICKS ,C.AD_SALES ,C.CONVERSIONS ,D.Shipment_cost ,CASE WHEN LOWER(a.marketplace) LIKE ANY (\'%shopify%\',\'%website%\') THEN 42000 WHEN LOWER(a.marketplace) LIKE \'%myntra%\' THEN (IFNULL(a.GROSS_SALES_BEFORE_TAX,0) - IFNULL(a.RETURN_AMOUNT,0)) * 0.38 WHEN LOWER(a.marketplace) LIKE \'%amazon%\' THEN (IFNULL(a.GROSS_SALES_BEFORE_TAX,0) + IFNULL(a.TAX,0) - IFNULL(a.RETURN_AMOUNT,0)) * 0.22 WHEN LOWER(a.marketplace) LIKE \'%cocoblu_blr%\' THEN (IFNULL(a.GROSS_SALES_BEFORE_TAX,0) + IFNULL(a.TAX,0) - IFNULL(a.RETURN_AMOUNT,0)) * 0.20 WHEN LOWER(a.marketplace) LIKE \'%flipkart%\' THEN (IFNULL(a.GROSS_SALES_BEFORE_TAX,0) - IFNULL(a.RETURN_AMOUNT,0)) * 0.38 END AS Commission_amount ,CASE WHEN UPPER(A.channel) LIKE ANY(\'%FACEBOOK%\',\'%INSTAGRAM%\',\'%META%\') THEN \'FACEBOOK\' WHEN UPPER(A.channel) LIKE \'%GOOGLE%\' THEN \'GOOGLE\' WHEN UPPER(A.channel) LIKE ANY (\'%AMAZON%\',\'%COCOBLU%\') THEN \'AMAZON\' WHEN UPPER(A.channel) LIKE \'%FLIPKART%\' THEN \'FLIPKART\' ELSE \'OTHERS\' END AS CHANNEL FROM MAPLEMONK.PLAETO_PANDL_INTERMEDIATE A LEFT JOIN ( SELECT * FROM ( SELECT SKUCode_K_A_ AS SKUCODE ,MasterSKUCode AS MASTER_SKU ,CAST(NULLIF(TRIM(FOB), \'NA\') AS FLOAT64) AS COGS ,CAST(NULLIF(TRIM(MRP), \'NA\') AS FLOAT64) AS MRP ,Size ,Colour ,Style_Code ,Flipkart_FSN ,Sub_Style_Name ,Main_Style_Name ,Category___Gender AS CATEGORY_GENDER ,Product_Name__Display AS PRODUCT_NAME ,CAST(NULL AS FLOAT64) AS PACKAGING_COST ,ROW_NUMBER() OVER (PARTITION BY LOWER(REPLACE(SKUCode_K_A_,\' \',\'\')) ORDER BY 1) rw FROM `maplemonk.Plaeto_GS_SKU_MASTER` ) WHERE rw = 1 ) B ON LOWER(REPLACE(A.sku,\' \',\'\')) = LOWER(REPLACE(B.SKUCODE,\' \',\'\')) FULL OUTER JOIN ( SELECT date ,CASE WHEN LOWER(channel) LIKE \'%facebook%\' THEN \'FACEBOOK\' WHEN LOWER(channel) LIKE \'%google%\' THEN \'GOOGLE\' WHEN LOWER(channel) LIKE \'%amazon%\' THEN \'AMAZON\' WHEN LOWER(channel) LIKE \'%flipkart%\' THEN \'FLIPKART\' WHEN LOWER(channel) LIKE \'%myntra%\' THEN \'MYNTRA\' ELSE UPPER(channel) END AS Marketplace ,UPPER(channel) marketing_Channel ,SUM(IFNULL(spend,0)) AS spend ,SUM(IFNULL(impressions,0)) AS impressions ,SUM(IFNULL(clicks,0)) AS clicks ,SUM(IFNULL(conversions,0)) AS conversions ,SUM(IFNULL(conversion_value,0)) AS ad_sales FROM plaeup-wh.maplemonk.plaeup_wh_MARKETING_CONSOLIDATED GROUP BY 1,2,3 ) C ON A.order_date = C.date AND UPPER(IFNULL(A.channel,\'\')) = UPPER(C.marketing_Channel) LEFT JOIN ( SELECT * FROM ( SELECT CAST(Shipment_cost AS FLOAT64) Shipment_cost, CASE WHEN LOWER(marketplace) LIKE \'%plaeto%\' THEN \'WEBSITE\' WHEN LOWER(marketplace) LIKE \'%amazon%\' THEN \'AMAZON\' WHEN LOWER(marketplace) LIKE \'%flipkart%\' THEN \'FLIPKART\' WHEN LOWER(marketplace) LIKE \'%myntra%\' THEN \'MYNTRA\' ELSE \'OTHERS\' END AS final_marketplace, ROW_NUMBER() OVER ( PARTITION BY UPPER(REPLACE(Marketplace, \' \', \'\')) ORDER BY 1 ) AS rw FROM `maplemonk.Plaeto_gs_SHIPMENT_COSTS` ) WHERE rw = 1 ) D ON LOWER(REPLACE(A.final_marketplace,\' \',\'\')) = LOWER(REPLACE(D.final_marketplace,\' \',\'\')) LEFT JOIN ( SELECT DISTINCT CASE WHEN REPLACE(LOWER(TRIM(marketplace)), \' \', \'\') LIKE \'%amazon.in_vp_df%\' THEN \'COCOBLU_BLR\' WHEN REPLACE(LOWER(TRIM(marketplace)), \' \', \'\') LIKE \'%amazon.in_vp%\' THEN \'AMAZON\' WHEN LOWER(TRIM(marketplace)) LIKE \'%flipkart%\' THEN \'FLIPKART\' WHEN LOWER(TRIM(marketplace)) LIKE \'%myntra%\' THEN \'MYNTRA\' WHEN LOWER(TRIM(marketplace)) LIKE \'%plaeto.in%\' THEN \'WEBSITE\' END AS MARKETPLACE, commission_value FROM `maplemonk.Plaeto_gs_Marketplace_Commissions` ) E ON LOWER(A.marketplace) = LOWER(E.marketplace);",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            